#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {  int nCount;  POINT pt;  bool last;  } Queue_Lines;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintLinesX(DefinePaint)  {  QueueP(Queue_Lines);  int nCount = ( p->last ) ? p->nCount : p->nCount-1 ;  for ( int n = 0; n <= nCount; n++ )    {    int y = ( p->mRect.top*(p->nCount-n) + p->mRect.bottom*n )/p->nCount;    if ( p->pt.x == 0 )      {      ::MoveToEx( hDC, p->mRect.left , y, NULL );      ::LineTo  ( hDC, p->mRect.right, y );      }    else      {      int x0 = p->mRect.left;      int x1 = p->mRect.right;      if ( ( n % p->pt.x ) == 0 )        {        if ( p->pt.y < p->mRect.left  ) x0 = p->pt.y;        if ( p->pt.y > p->mRect.right ) x1 = p->pt.y;        }      ::MoveToEx( hDC, x0, y, NULL );      ::LineTo  ( hDC, x1, y );      }    }  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintLinesY(DefinePaint)  {  QueueP(Queue_Lines);  int nCount = ( p->last ) ? p->nCount : p->nCount-1 ;  for ( int n = 0; n <= nCount; n++ )    {    int x = ( p->mRect.left*(p->nCount-n) + p->mRect.right*n )/p->nCount;    if ( p->pt.x == 0 )      {      ::MoveToEx( hDC, x, p->mRect.top, NULL );      ::LineTo  ( hDC, x, p->mRect.bottom );      }    else      {      int y0 = p->mRect.top;      int y1 = p->mRect.bottom;      if ( ( n % p->pt.x ) == 0 )        {        if ( p->pt.y < p->mRect.top    ) y0 = p->pt.y;        if ( p->pt.y > p->mRect.bottom ) y1 = p->pt.y;        }      ::MoveToEx( hDC, x, y0, NULL );      ::LineTo  ( hDC, x, y1 );      }    }  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~static Queue_Lines* AddLines(DefineTegs)  {  AddQueueEX(Queue_Lines);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  p->last = true;  //  STegObj obj[] =    {    { 'R', "rect", &p->mRect   },    { 'E', "rc"  , &p->mRect   },    { 'P', "pt"  , &p->pt   },    { 'L', "last", &p->last },    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  //  p->nCount = Atoi( teg[0].value )-1;  //  return p;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddLinesX(DefineTegs)  {  Queue_Lines* p = AddLines( def, teg, Buffer, rLog );  // Определение функции вывода  p->paint = &PaintLinesX;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddLinesY(DefineTegs)  {  Queue_Lines* p = AddLines( def, teg, Buffer, rLog );  // Определение функции вывода  p->paint = &PaintLinesY;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~